/* Content data for the seminar guide (single source for every section). */
window.SEMINAR_DATA={"SAMPLES":{"MP":{"name":"Metal-poor","sub":"$\\MH\\lt -1.5$","N":"29,995 to 30,589","def":"The stated metal-poor cut."},"SN":{"name":"High-significance","sub":"parallax $\\SN\\ge 5$","N":"16,840 to 17,213","def":"Adds a parallax signal-to-noise requirement. The manuscript does not say whether it sits on top of the $\\MH$ cut; the smaller $N$ suggests so."},"AS":{"name":"High-sig. + astrometry","sub":"$\\SN\\ge 5$, $\\RUWE\\lt 1.4$","N":"16,698 to 17,050","def":"Adds a $\\RUWE\\lt 1.4$ astrometric quality cut."}},"MASKS":{"full":"Full sky","b5":"$|b|\\gt 5^\\circ$"},"PATHS":[{"id":"P01","sample":"MP","mask":"full","zp":0,"v":3.5292},{"id":"P02","sample":"MP","mask":"full","zp":1,"v":2.7033},{"id":"P03","sample":"MP","mask":"b5","zp":0,"v":3.5264},{"id":"P04","sample":"MP","mask":"b5","zp":1,"v":2.6849},{"id":"P05","sample":"SN","mask":"full","zp":0,"v":2.2087},{"id":"P06","sample":"SN","mask":"full","zp":1,"v":2.241},{"id":"P07","sample":"SN","mask":"b5","zp":0,"v":2.1708},{"id":"P08","sample":"SN","mask":"b5","zp":1,"v":2.2058},{"id":"P09","sample":"AS","mask":"full","zp":0,"v":2.1957},{"id":"P10","sample":"AS","mask":"full","zp":1,"v":2.2285},{"id":"P11","sample":"AS","mask":"b5","zp":0,"v":2.1608},{"id":"P12","sample":"AS","mask":"b5","zp":1,"v":2.1951}],"STORY":[{"t":"ApJ case","s":"Rix et al. 2022","h":"Reproduce one paper, several models","b":"Using Hermes, several LLMs ran multiple independent reproductions of “The Poor Old Heart of the Milky Way”. Every run recovered the central qualitative result.","x":["Sample size: about 30,000 stars from the stated method versus roughly 18,000 to 20,000 published.","$\\sigma_{\\mathrm{RGC}}$: the public method did not uniquely determine the published $2.7\\kpc$."]},{"t":"Suspect the system","s":"Refine the pipeline","h":"Blame the agent first","b":"The authors could not tell whether the failure was a missing clue in the paper, their own lack of domain expertise, a hidden pipeline defect or a model-tool failure. They set out to reduce interference from pipeline, agents, models and human operation.","x":["New goal: reproduce a small group of papers from the same field while refining the workflow."]},{"t":"Thirteen papers","s":"Nature, 2021 to 2026","h":"Batch reproduction and audit","b":"Each paper ran in two rounds with different foundation models. An adjudicator reconciled them and a human expert reviewed each retained item.","x":["11 of 13 had at least one issue blocking a unique path.","Only 2 supported an independent path from data to the target number within the task scope."]},{"t":"Pivot","s":"From validating to discovering","h":"Reproduction as a probe","b":"Attention moved from the system solving the problem to the information in the problem. A verified discrepancy may expose a relationship among data, method and conclusion that was never made explicit.","x":["Reproduction is repositioned as an entry point to hidden knowledge, not only a validity check."]},{"t":"Back to Rix","s":"12 predefined paths","h":"Controlled sensitivity analysis","b":"The authors stopped tuning toward $2.7\\kpc$ and asked how much scientifically plausible choices change the conclusion.","x":["Sample definition $\\times$ sky mask $\\times$ zero-point $=12$ paths.","All executed. $\\sigma_{\\mathrm{RGC}}$ from $2.16$ to $3.53\\kpc$; one path near 2.70."]},{"t":"Insight","s":"Present but unlinked","h":"What the matching path revealed","b":"The $+0.02\\mas$ correction was already in the paper. The agents did not recognise its causal relevance until the experiment made the effect visible.","x":["A numerical match is neither necessary evidence of correct reasoning nor a stable target."]}],"THREE":[{"t":"Agent or tooling error","c":"p","b":"A pipeline defect, a model-tool failure, a coding mistake or missing domain expertise on the authors’ side.","h":"Infrastructure errors isolated and fixed; independent verifier; cross-model audit; provenance logs.","e":"This was the authors’ first suspect (§4.1 to 4.2)."},{"t":"Source underspecification","c":"p","b":"The paper allows more than one executable path. A human expert closes the gap with convention; an agent forks.","h":"Record the ambiguity instead of tuning; enumerate the forks; run them all.","e":"11 of 13 audit; twelve-path spread of $2.16$ to $3.53\\kpc$."},{"t":"Failure to connect information","c":"p","b":"The needed fact is in the paper but the agent does not see that it governs a downstream step.","h":"Only detectable when an experiment makes the fact’s effect visible.","e":"The $+0.02\\mas$ correction. The paper’s most original claim."}],"CONTRIB":[{"t":"Reproduction as a probe of implicit knowledge","p":"Rather than asking whether an agent can make a discovery, the paper asks whether it can retrace one end to end. A non-unique reproduction path becomes a measurable signal of knowledge the paper leaves implicit.","ev":3,"n":"Clean and new as a framing. The operational definition is broad."},{"t":"An auditable multi-agent workflow","p":"Five roles (reader, planner, coder, verifier, adjudicator) on Hermes, with provenance, pinned environments, cross-model audit and mandatory uncertainty reporting. Execution is separated from adjudication to limit self-confirmation.","ev":3,"n":"Sound principles. Few implementation details in the manuscript."},{"t":"Corpus-level evidence of recurring gaps","p":"Of 13 Nature astronomy papers, 11 had at least one blocking issue and 10 omitted critical settings. Only 2 supported an independent data-to-number path.","ev":2,"n":"Striking headline on a low threshold, small N and confounded with agent reading."},{"t":"A blinded factorial sensitivity analysis","p":"Three degrees of freedom crossed into 12 paths spanning $2.16$ to $3.53\\kpc$. The published value was never a target, and the matching path was identified after all runs.","ev":4,"n":"Best part of the paper: transparent design, vivid result. Blinding is self-attested."},{"t":"Present but unlinked information","p":"The $+0.02\\mas$ correction was in the paper and cited to Lindegren et al. (2021). The agents parsed and used the number but had not linked it to the fit until its effect became visible.","ev":2,"n":"Most interesting claim, resting on one narrative case with no ablation."},{"t":"A new reading of what a numerical match means","p":"A match is neither necessary nor sufficient evidence of reconstructed reasoning and cannot be an optimisation target. Reproduction may also surface hidden knowledge.","ev":3,"n":"First half follows from the spread. Second half is aspirational, as the authors concede."}],"CLAIMS":[["11 of 13 Nature papers had at least one ambiguity","Fig. 6, Appendix A, §4.2","Count shown, items paraphrased; the audit table is supplementary",2],["Twelve paths give $\\sigma_{\\mathrm{RGC}}$ from $2.16$ to $3.53\\kpc$","Fig. 8, §4.3","Values printed in the figure; configurations promised in a package",4],["The published value was never used for tuning","§3.5, §4.3","Attestation only; logs would be needed",3],["Agents did not recognise the causal relevance of $+0.02\\mas$","§4.3, §6","Narrative; no ablation or run counts",2],["Matching a number does not validate reasoning","Abstract, §6, §8","Follows from the spread of path values",4],["Reproduction can reveal hidden knowledge","§4.2, §8","Stated as a possibility; the authors claim no discovery",1]],"BG":[{"t":"The reproducibility problem","k":"b","b":"Surveys of researchers find that many published results are hard or impossible to reproduce (Baker 2016, 1,500 scientists). Methodological work asks for dependency capture, provenance and executable environments (Peng 2011; Stodden et al. 2014).","w":"The paper keeps that vocabulary but changes the purpose. Reproduction is used as a diagnostic that shows which steps a publication leaves implicit."},{"t":"Tacit and implicit knowledge","k":"b","b":"Polanyi (1966) argued that people know more than they can tell. Collins (2010) separates kinds of tacit knowledge. The authors also cite Yann LeCun’s 2023 remark that much human knowledge is non-linguistic.","w":"The paper’s “implicit” knowledge is mostly conventions and judgments an author left unwritten. Strictly, that is unwritten, not tacit in Polanyi’s sense, because it could be written down."},{"t":"LLM agents","k":"b","b":"Transformers (Vaswani 2017) and large few-shot models (Brown 2020) made instruction-following assistants possible. Agents add tools and loops: ReAct interleaves reasoning with actions, Reflexion stores verbal self-critique, AutoGen coordinates several conversing agents.","w":"Hermes plays the AutoGen-like orchestration role here, and the verify-and-rerun loop echoes Reflexion. The paper treats the agent as the object of study."},{"t":"Autonomous AI scientists","k":"b","b":"Systems such as Coscientist-style chemistry agents (Boiko et al. 2023) and “AI Scientist” pipelines (Lu et al. 2024; Si et al. 2025) generate hypotheses, run experiments and draft papers.","w":"The authors’ point is that such discoveries are hard to evaluate because novelty has no immediate ground truth, so they evaluate on reproduction where the target is known."},{"t":"Gaia parallaxes and the zero-point","k":"b","b":"Gaia measures stellar parallaxes, the tiny annual shift of a star’s position. Distance is about $1/\\varpi$. Gaia EDR3 parallaxes carry a small systematic offset that depends on magnitude, colour and sky position (Lindegren et al. 2021). Its global size is roughly $0.02\\mas$, in the sense that measured parallaxes are slightly too small.","w":"At the Galactic centre ($\\approx 8\\kpc$) the true parallax is only about $0.125\\mas$, so a $0.02\\mas$ offset is a double-digit percentage of the signal. That is why the zero-point matters here."},{"t":"Rix et al. (2022) and the quantities involved","k":"b","b":"“The Poor Old Heart of the Milky Way” reports a centrally concentrated population of metal-poor stars ($\\MH\\lt -1.5$). $\\sigma_{\\mathrm{RGC}}$ is the paper’s spatial scale for that population, about $2.7\\kpc$. The case study draws on Gaia, APOGEE and a Zenodo table with kinematics.","w":"Quality indicators matter: parallax $\\SN=\\varpi/\\sigma_{\\varpi}$ and RUWE, a Gaia fit-quality statistic where values above about 1.4 flag poor astrometry."},{"t":"Sensitivity analyses and forking paths","k":"b","b":"Statisticians describe a “garden of forking paths” (Gelman and Loken 2013): reasonable analytic choices multiply and move results. Many-analyst studies (for example Silberzahn et al. 2018) give one dataset to several teams and find large spread.","w":"The twelve-path design is a small, systematic version of this idea applied to an AI agent. The paper does not cite this literature."}],"READ":[{"g":"Agents and tools","i":["Vaswani et al. 2017: the Transformer architecture","Brown et al. 2020: few-shot learning at scale","OpenAI 2023: GPT-4 technical report","Yao et al. 2023 (ReAct): reasoning interleaved with actions","Shinn et al. 2023 (Reflexion): verbal self-reflection in memory","Wu et al. 2023 (AutoGen): multi-agent conversation"]},{"g":"AI for science","i":["Boiko, MacKnight and Gomes 2023: LLM agents running chemical experiments","Lu et al. 2024: The AI Scientist","Si et al. 2025: end-to-end autonomous research","Nous Research 2026: Hermes Agent, the framework used"]},{"g":"Reproducibility and knowledge","i":["Baker 2016: survey on reproducibility","Peng 2011 and Stodden et al. 2014: reproducible computational research","Polanyi 1966 and Collins 2010: tacit knowledge"]},{"g":"Astronomy case","i":["Rix et al. 2022: the case-study paper","Lindegren et al. 2021: Gaia EDR3 parallax bias","Gaia Collaboration 2016, 2021 and ESA 2021: mission, release and zero-point code","Twelve Nature papers (2021 to 2026) in the audit corpus"]}],"AIROWS":[["Foundation LLMs (at least two, independent)","Extracted paper text, notes, tool output","Notes, task graphs, code, interpretations, verdicts","Stand in for the human reader who must reconstruct a method from prose.","Misreading, invented parameter values, missing links between distant passages."],["Agent loop with tools","A plan step plus observations from tools","Queries, scripts, updated state","A raw model cannot download data or run a fit. The loop turns reasoning into actions.","Silent defaults when the paper is vague; infrastructure errors mistaken for science."],["Role specialisation on Hermes","Role-specific context and shared files","Structured artefacts per role","Separates reading, planning, coding, checking and judging so failures can be located.","Hand-off loss: a fact recorded in notes but not marked as governing."],["Verifier and cross-model audit","Coder output, paper anchors, a second model’s reading","Agreement or a flagged discrepancy","Counters agents confirming their own work.","Correlated errors across models trained on similar data."],["Persistent filesystem and provenance","Every dataset, script, intermediate result, parameter decision","An auditable trail","Lets each number be traced to the choice that produced it.","Completeness depends on discipline; not shown in the manuscript."],["Human domain expert","Reconciled audit items","Retained or dropped items","Supplies domain judgment agents lack. The paper says auditing cannot replace domain experience.","Subjective coding; no inter-rater statistic reported."]],"TRACE":[{"t":"Thought","s":"Define the sample","k":"think","x":"The paper defines the metal-poor population as $\\MH\\lt -1.5$. I need that table of stars."},{"t":"Action","s":"Query the data","k":"act","x":"Load the Zenodo table and cross-match to Gaia by source_id. Apply the stated cut."},{"t":"Observation","s":"Count mismatch","k":"obs","x":"30,589 unique stars. The paper’s analysis used roughly 18,000 to 20,000."},{"t":"Thought","s":"Trace upstream","k":"think","x":"Mismatch at stage 04 (compare). Find the earliest unsupported assumption: subsample, quality cuts, deduplication or data version."},{"t":"Action","s":"Build an explicit ladder","k":"act","x":"Add cuts one at a time and log each count with provenance."},{"t":"Observation","s":"Still no match","k":"obs","x":"15,063 with Zenodo kinematics, 13,141 after the cut $\\varpi<0.25\\mas$. Neither reproduces the published count."},{"t":"Verifier","s":"Independent check","k":"ver","x":"Re-derive the counts separately. They agree with the coder’s."},{"t":"Adjudicator","s":"Cross-model audit","k":"adj","x":"A different model reviews the record. The discrepancy stands and is labelled an unresolved sample-definition gap, not tuned away."}],"ROLES":{"reader":{"n":"Reader","tg":"p","does":"Parses the target paper and accessible supplementary material into structured notes.","reads":"Extracted text of the paper and supplement.","writes":"Notes: research question, methods, key claims, numbers that can act as validation anchors.","decides":"What counts as method, claim or anchor; which numbers to carry forward.","risks":["PDF extraction can corrupt equations and tables; the appendix cites a mangled normalisation coefficient and a garbled exponent.","Notes are a lossy summary. A value can be kept as a fact without being marked as governing a later step."],"silent":"Parser, OCR, whether figures are viewed as images."},"planner":{"n":"Planner","tg":"p","does":"Decomposes the reproduction into an executable task graph and compiles claims into tasks with validation anchors and criteria.","reads":"Reader’s notes.","writes":"Task graph with ordering, data needs, success criteria.","decides":"Task order, which public data to use, what counts as a match.","risks":["Many papers give no numerical tolerance, so criteria must be invented.","Alternative interpretations must be enumerated deliberately; a planner that picks one reading hides the fork."],"silent":"Whether the planner or a human enumerated the twelve paths."},"coder":{"n":"Coder","tg":"p","does":"Writes and executes the analysis in a sandboxed Python environment, fetching public data.","reads":"Task graph, environment, archives.","writes":"Scripts, intermediate outputs, figures, with provenance for every parameter decision.","decides":"Every unspecified cut, prior, solver setting and binning.","risks":["Each unspecified detail is a silent fork. The audit exists to stop agents forcing missing pieces into place just to obtain an answer."],"silent":"Retry limits; how defaults are chosen."},"verifier":{"n":"Verifier","tg":"p","does":"Independently re-derives results and checks them against the paper, point by point.","reads":"Coder’s outputs and the paper’s anchors.","writes":"Agreement, discrepancy reports, quantitative checks.","decides":"Whether a mismatch is real, and its likely stage of origin.","risks":["If it shares a model or context with the coder, it can inherit the same misreading."],"silent":"What the verifier sees of the coder’s reasoning."},"adjudicator":{"n":"Adjudicator","tg":"p","does":"Resolves execution and verification disagreements through cross-model audit rather than self-confirmation, and reconciles the two rounds in the Nature audit.","reads":"Both models’ records and the verifier’s reports.","writes":"Reconciled judgment: reproduced, not uniquely specified, or agent error; plus a gap record.","decides":"Which disagreements are real and which are artefacts.","risks":["Cross-model agreement is weaker evidence when models share training data."],"silent":"Escalation path for unresolved cases (dashed arrow is my inference)."},"input":{"n":"Input","tg":"p","does":"The target paper and any accessible supplementary material, plus public datasets.","reads":"Journal PDFs, archives.","writes":"—","decides":"—","risks":["Access varies: appendix notes cases of partial main text and missing Extended Data cells."],"silent":"Whether authors’ code or correspondence were ever used. Public material only appears to be allowed."},"human":{"n":"Human expert review","tg":"p","does":"A domain expert reviews every retained audit item, after the adjudicator reconciles two model rounds.","reads":"Reconciled audit records.","writes":"Retained, dropped or unverified labels.","decides":"Which observations count as real ambiguities.","risks":["Coding is partly interpretive and could differ for another team (the authors’ own limitation).","No inter-rater reliability is reported."],"silent":"Number of reviewers and their expertise."},"models":{"n":"Foundation models","tg":"p","does":"At least two independent frontier LLMs act as the reasoning engines, so no conclusion rests on one architecture.","reads":"Context assembled by the framework.","writes":"Reasoning, code and verdicts for each role.","decides":"Everything the agent decides.","risks":["Identifiers, versions, temperature, seeds and run counts are placeholders in this manuscript.","Possible exposure to Rix et al. (2022) during training is not discussed."],"silent":"Which model fills which role."},"fs":{"n":"Filesystem and provenance","tg":"p","does":"A persistent filesystem holds every downloaded dataset, generated script, intermediate output and parameter decision, with provenance.","reads":"All roles.","writes":"All roles.","decides":"—","risks":["A shared file store is probably the main channel between roles (my inference), so a missing note is a missing fact for everyone downstream."],"silent":"Schema of the provenance log."},"tools":{"n":"Toolchain","tg":"p","does":"Web and scholarly retrieval, public astronomical archives (Gaia, plus MAST, TESS and survey releases where relevant), a sandboxed Python environment with pinned packages, and shell access.","reads":"Agent requests.","writes":"Data, logs, results.","decides":"—","risks":["Archive releases change, so a reproduction can depend on the date it was run (acknowledged limitation)."],"silent":"—"}},"PIPE":[{"t":"Read the paper","s":"Understand the problem","who":"Reader","inp":"Paper and accessible supplement","out":"Research question, methods and key claims as structured notes","chk":"Notes cover each numeric claim; unreadable text is flagged.","gap":"Extraction corruption, missing Extended Data."},{"t":"Design the plan","s":"Compile claims into tasks","who":"Planner","inp":"Structured notes","out":"Executable steps with validation anchors and criteria","chk":"Every anchor maps to a step; criteria recorded before running.","gap":"Papers rarely state tolerances."},{"t":"Prepare the stack","s":"Build runnable conditions","who":"Coder, toolchain","inp":"Plan, public data and code, software dependencies","out":"A pinned environment and downloaded data with provenance","chk":"Versions pinned; datasets logged.","gap":"Unavailable simulation grids or templates."},{"t":"Run and verify","s":"Test every result","who":"Coder, verifier","inp":"Environment and plan","out":"Data processing, analysis, and a point-by-point comparison with the paper","chk":"Independent re-derivation; mismatches routed to the tracing loop.","gap":"Silent defaults for unspecified settings."},{"t":"Form a judgment","s":"Turn gaps into insight","who":"Adjudicator, human expert","inp":"All records, from two models","out":"Reproduction verdict, attribution of differences, new questions","chk":"Cross-model audit; expert review of every retained item; unverified items kept separate.","gap":"Subjective coding; no reliability statistic."}],"RIX":[{"t":"Inventory","s":"Zenodo, Gaia, APOGEE","b":"List every data source the paper relies on and what each provides.","x":"Establishes what can be obtained publicly before any analysis."},{"t":"Cross-match","s":"source_id audit","b":"Join the tables on Gaia source_id and audit duplicates and missing rows.","x":"Feeds the unique-star count (30,589 in the Zenodo table)."},{"t":"Reproduce","s":"Figures 2 to 7","b":"Re-create the paper’s figures from the cross-matched data.","x":"Qualitative trends recovered in every run."},{"t":"Compare","s":"Paper anchors","b":"Compare against published numbers.","x":"Sample size and $\\sigma_{\\mathrm{RGC}}$ anomalies appear here."},{"t":"Diagnose","s":"Data, method, numbers","b":"Classify each mismatch as data, method or numerical, and trace it to the earliest unsupported assumption.","x":"Loop back to the earliest affected stage (01 to 04)."},{"t":"Review","s":"Paper, appendix, citations","b":"Re-read the paper, appendix and cited work for clues.","x":"Where the $+0.02\\mas$ value and its Lindegren citation sit unlinked."}],"CATS":[{"k":"any","n":11,"t":"At least one issue","d":"Overall result. Only two of the thirteen papers described their method completely enough, within the task scope, to support an independent path from data to the target number."},{"k":"crit","n":10,"t":"Critical settings omitted","d":"Examples named in the figure: MCMC settings, binning, PSF versions, convergence criteria."},{"k":"num","n":8,"t":"Numerical conflict or ambiguity","d":"Two values for one quantity; ambiguous units or symbols."},{"k":"role","n":6,"t":"Ambiguous role of a term or value","d":"Is a number a validation input, or a result to be reproduced?"},{"k":"chain","n":6,"t":"Broken methodological chain","d":"A skipped derivation; unavailable templates or simulation grids."},{"k":"contra","n":5,"t":"Internal contradiction","d":"Claims in text, captions or sections that cannot all hold."}],"TYPES":{"config":"Missing configuration","incons":"Internal inconsistency","role":"Role or meaning ambiguity","units":"Units or precision","extract":"Extraction or access artefact"},"PAPERS":[{"n":1,"s":"Detection of anisotropic cosmic structures on a gigaparsec scale","v":"Nature 2026","tp":"Cosmology, large-scale structure","g":"DESI galaxy survey and a parameter-free statistic suggest anisotropy beyond simulations, challenging the cosmological principle.","ty":["incons","config","extract"],"c":["Three different simulation sample sizes appear (330 in text, 1,000 and 200 in figure panels) for one test.","The “representative BGS subsample” is not defined; angular bins and radial-bin boundaries are not given.","The normalisation in the angular-variance formula is corrupted in the extracted text; “1,0243” could be 1024³."]},{"n":2,"s":"GW250114 reveals signatures of post-merger black-hole horizon","v":"Nature 2026","tp":"Gravitational waves, black holes","g":"Signatures of horizon behaviour after merger; tests Einsteinian gravity.","ty":["units","config","incons","role"],"c":["Units of the damping rate are not stated.","Source of the NRSur7dq4 waveform is not given, only a theory citation.","“Fully consistent” with Kerr theory is stated without a metric, while another statement says one frequency need not match exactly.","Two readings assign different roles to the “300 simulated backgrounds”."]},{"n":3,"s":"A direct black-hole mass measurement in a little red dot at high redshift","v":"Nature 2026","tp":"JWST, black-hole mass","g":"Direct dynamical measurement of a black-hole mass at high redshift.","ty":["role","extract"],"c":["The same $\\approx 10\\ \\mathrm{km\\,s^{-1}}$ value appears with two meanings: a velocity gradient and a projected velocity per bin.","Uncertainty values are unreliable in the visible text.","Readers disagree on whether the stellar mass and inclination are reference answers or validation inputs."]},{"n":4,"s":"An ultra-faint, chemically primitive galaxy forming in the reionization era","v":"Nature 2026","tp":"JWST, early galaxies","g":"An extremely faint, metal-poor dwarf galaxy from the reionisation epoch.","ty":["config","role"],"c":["Readings disagree on the applicable scope of method M07 and on how strongly the hard-spectrum interpretation is supported.","The complete method chain for the dynamical mass is missing."]},{"n":5,"s":"Satellite megaconstellations will threaten space-based astronomy","v":"Nature 2025","tp":"Space policy, satellite constellations","g":"Starlink-like constellations threaten ground and space observations.","ty":["incons","extract"],"c":["SPHEREx altitude is $650\\,\\mathrm{km}$ in one place and $700\\,\\mathrm{km}$ in the overview.","Hubble exposure-time bounds are reconstructed values and need checking against the original."]},{"n":6,"s":"Witnessing the onset of reionization through Lyman-$\\alpha$ emission at redshift 13","v":"Nature 2025","tp":"JWST, cosmic reionisation","g":"Lyman-$\\alpha$ emission at $z=13$ as a view of the onset of reionisation.","ty":["config","role"],"c":["Readings disagree on how the systemic redshift was determined.","Neither reading can recover the EDT3 prior or most posterior-table values; $\\sigma$-clipping, covariance construction and path-loss correction are unspecified.","ForcePho photometry and morphology settings are incomplete: no version, no PSF."]},{"n":7,"s":"Spectroscopic confirmation of two luminous galaxies at a redshift of 14","v":"Nature 2024","tp":"JWST, high-z galaxies","g":"Spectroscopy confirms two luminous galaxies at $z=14$.","ty":["units","role","config"],"c":["Units of the slit-loss polynomial are not stated for the $z=14.0$ galaxy.","The shared parameter U5 is used with conflicting meanings.","No numerical tolerance; sampler, likelihood and convergence criteria are missing; single exposures, per-exposure PSFs and software versions for morphology fitting are not provided."]},{"n":8,"s":"Fast-moving stars around an intermediate-mass black hole in $\\omega$ Centauri","v":"Nature 2024","tp":"Black holes, globular clusters","g":"High-velocity stars in $\\omega$ Cen indicate an intermediate-mass black hole.","ty":["config","extract"],"c":["Readings disagree on whether robustness tests extended to the surface-brightness model, mass-to-light ratio and distance.","Full MCMC configuration and grid bounds are missing; the external N-body simulation grid is unavailable.","Extended Data Table 1 has missing cells that both readings needed."]},{"n":9,"s":"A resonant sextuplet of sub-Neptunes transiting the bright star HD 110067","v":"Nature 2023","tp":"Exoplanets, resonant chains","g":"Six planets in a $3{:}2$/$4{:}3$ period-resonance chain; two recovered by reprocessing TESS data.","ty":["incons","extract"],"c":["Text says $120\\,\\mathrm{s}$ sampling; the caption gives 2 minutes for Sector 23 and 20 seconds for Sector 49.","Predicted period of planet g is 54.7433 d versus 54.76992 d measured. A 0.0266 d gap is 133 times the error bar, and has been explained by the detunings of adjacent pairs.","The $\\pm$ ordering of asymmetric uncertainties was rebuilt from corrupted cells and still needs checking."]},{"n":10,"s":"The solar dynamo begins near the surface","v":"Nature 2024","tp":"Solar physics","g":"The solar dynamo begins near the surface rather than deep in the interior.","ty":["extract","config"],"c":["Both readings agree on the rotation-profile equation, but the assembled formula lacks a parameter. The extraction was repeated with a different OCR tool."]},{"n":11,"s":"Orbital period change of Dimorphos due to the DART kinetic impact","v":"Nature 2023","tp":"Planetary science, DART","g":"Measured change in the orbital period of Dimorphos after impact.","ty":["units","role"],"c":["The pre-impact period appears at two precision levels, $11.92148\\pm0.00013\\ \\mathrm{h}$ ($3\\sigma$) and a rounded form.","Readings classify it differently as an external input or a method output.","No tolerance is given. One reading includes an initial radar estimate of $-36\\pm15$ minutes and the other omits it. The formal run was not completed; an earlier shadow-experiment record was used."]},{"n":12,"s":"Star formation near the Sun is driven by expansion of the Local Bubble","v":"Nature 2021","tp":"Milky Way, star formation","g":"Expansion of the Local Bubble drives nearby star formation.","ty":["config","extract"],"c":["“Qualitative morphology” has no metric or threshold; the expansion model is idealised and its exponent was inferred from a standard form in an external citation.","The Milky Way-like potential variant and integration settings are unspecified; the cluster catalogue, ages and dust geometry are external and missing."]},{"n":13,"s":"A dormant overmassive black hole in the early Universe","v":"Nature 2024","tp":"JWST, early black holes","g":"A dormant, overmassive black hole in the early Universe.","ty":["units","extract"],"c":["Units of black-hole mass and host stellar mass are ambiguous.","Whether the actual method uses a virial workflow is unverified; one reading saw only part of the main text.","Data described as “expected to be public” is only an expectation. The ~$10^{45}$ luminosity is a “corrected” target and the corrected-versus-uncorrected chain is unclear."]}],"ASSUMP":[{"g":"Evaluation design","k":"explicit","t":"Reproduction is a valid stand-in for evaluating scientific reasoning","x":"§2 reframes discovery as end-to-end reproduction so that a verifiable target exists.","r":"Retracing a known path may test reading and execution more than hypothesis generation, so success may not predict performance on open problems."},{"g":"Evaluation design","k":"implicit","t":"A non-unique path means the paper is under-specified, not that the reader lacks expertise","x":"Every unresolved fork is treated as an information gap in the source.","r":"No human baseline is reported. Expert humans may resolve many forks by convention, so the ambiguity rate for experts could be far below 11 of 13."},{"g":"Evaluation design","k":"explicit","t":"The chosen papers’ headline conclusions are broadly accepted","x":"Eligibility criterion 3: discrepancies should not be attributable to contested science.","r":"Acceptance is judged by the authors. A mismatch could still reflect a genuine error or a later data revision."},{"g":"Evaluation design","k":"explicit","t":"Public data and public text suffice to define a reproduction task","x":"Eligibility criteria 1 and 2.","r":"Author code, private data and correspondence, which human reproducers often use, are excluded. Some “gaps” are access limits."},{"g":"Corpus","k":"implicit","t":"The thirteen Nature papers say something about the wider literature","x":"Used to claim a recurring pattern “within this corpus”.","r":"How the thirteen were chosen from eligible papers is not described. Nature’s length limits push detail into Methods and Extended Data, which agents may only partly reach."},{"g":"Corpus","k":"explicit","t":"Astronomy is a suitable testbed","x":"Open archives and computational analyses (§1, §7).","r":"The authors note rates may differ in other fields. Many papers are JWST-era fitting pipelines, which are long and parameter-heavy."},{"g":"Agents and models","k":"explicit","t":"Separating execution from adjudication reduces self-confirmation","x":"§2: cross-model audits, preserved artefacts, provenance and failure reporting.","r":"Assumes different models err independently. Frontier models share training data and failure modes, so correlated mistakes can survive an audit."},{"g":"Agents and models","k":"explicit","t":"Infrastructure errors were isolated and resolved","x":"§2: attention shifted from the problem-solving system to the source material.","r":"How this was shown is not given. Residual pipeline defects could still contribute to forks."},{"g":"Agents and models","k":"implicit","t":"Text extraction is faithful enough to the PDF","x":"Agents work from extracted text; the appendix notes corruption.","r":"Corrupted equations and table cells can pass as paper ambiguity. Such items are marked unverified, but the main count is not broken down by this."},{"g":"Agents and models","k":"implicit","t":"The failed link reflects a reasoning limit, not a prompting or context limit","x":"Interpretation of the $+0.02\\mas$ episode.","r":"No ablation is reported, such as prompting about calibration corrections or a different notes format. The Reader’s notes may simply have compressed the link away."},{"g":"Agents and models","k":"implicit","t":"The evaluated agents represent “LLM agents”","x":"Model identifiers, temperature, seeds and run counts are placeholders in this version.","r":"Claims about LLM limits cannot yet be tied to specific systems, and capability changes quickly (acknowledged in §7)."},{"g":"Controlled case study","k":"explicit","t":"The published value did not influence path generation","x":"§3.5 and §4.3: grid, labels and stopping rule frozen before running; no path added, removed or re-weighted.","r":"Self-attested. The team knew the target and the earlier mismatch when choosing factors, and the models may have seen Rix et al. (2022) in training."},{"g":"Controlled case study","k":"implicit","t":"Three factors capture the relevant degrees of freedom","x":"Sample definition, sky mask and zero-point.","r":"Distance estimator, Galactocentric constants, quality cuts, fitting model and priors were each fixed to one choice. Any of them could move the result as much as the zero-point."},{"g":"Controlled case study","k":"implicit","t":"“Closely matching” is a meaningful criterion","x":"$2.70\\kpc$ is said to closely match about $2.7\\kpc$ with no stated tolerance.","r":"A second path ($2.68\\kpc$) is within about $0.6\\%$. The paper criticises other papers for missing tolerances, yet gives none for its own match."},{"g":"Controlled case study","k":"implicit","t":"Matching $\\sigma$ implies matching the published pipeline","x":"The matching path uses the stated metal-poor cut, full sky and $+0.02\\mas$.","r":"That path has about 30,000 stars against the published 18,000 to 20,000, so the agreement is either coincidence or evidence of an unstated step."},{"g":"Astronomy","k":"implicit","t":"A single constant offset is an acceptable zero-point model","x":"$+0.02\\mas$ applied as a fixed shift.","r":"Lindegren et al. (2021) describe a bias depending on magnitude, colour and position. The paper itself says the rationale for a constant was compressed."},{"g":"Astronomy","k":"implicit","t":"Sample definition choices are scientifically neutral alternatives","x":"Three alternatives were treated as equally plausible.","r":"$\\SN$ cuts truncate distant stars and mechanically shrink the inferred scale, so the three samples are not equally suitable for an extended population."},{"g":"Inference","k":"implicit","t":"One quantity in one paper supports a general mechanism","x":"“Present but unlinked causal information” is offered as a limit of evaluated agents.","r":"Acknowledged in §7. Needs more papers, more quantities and more models."},{"g":"Inference","k":"implicit","t":"Large-scale reproduction can recover hidden knowledge","x":"Discussion: patterns may emerge from hundreds or thousands of papers.","r":"Speculative. No new knowledge is extracted here, and the authors say so."}],"DIMS":[["Novelty of the framing",4,"Treating a non-unique path as a measurable signal of implicit knowledge is a fresh and useful idea."],["Methodological rigour",3,"Strong in the sensitivity analysis, weak in the audit threshold and attribution."],["Strength of evidence",2,"One quantified case; no per-model results; no ablation; self-attested blinding."],["Generality",2,"Astronomy only; thirteen papers; one quantity."],["Transparency of the manuscript",2,"Model details are placeholders; audit and path configurations are promised later."],["Clarity and presentation",4,"Clear storyline and honest limitations section."],["Usefulness to the field",4,"A practical vocabulary and a template for sensitivity-based evaluation."]],"STRENGTHS":[["A precise reframing","Evaluating agents by their ability to retrace a published result sidesteps the ground-truth problem and makes reasoning observable."],["A pre-specified, blinded sensitivity analysis","Grid, labels and stopping rule fixed before running; all twelve paths executed; the match found only afterwards. This is the best-designed element."],["A vivid, quantified result","A $1.37\\kpc$ spread (about half the published value) from plausible choices makes the point that a match proves little."],["Separation of execution from adjudication","Verifier, cross-model audit, provenance and reporting of uncertainty and failure modes are sensible guards against self-confirmation."],["Candour about the first failure","The initial mismatch is reported as unresolved and the system, not the paper, is blamed first. The limitations section is frank."],["Careful wording about the appendix","Audit observations are explicitly not claims of error, and unverified items are separated from confirmed ones."],["A useful distinction","Retrieving a value, executing a procedure and recognising a value’s causal relevance are different abilities and can fail separately."],["Recent corpus","Papers from 2021 to 2026 reduce, but do not remove, the chance that models memorised the target."]],"WEAK":[{"sv":"high","t":"The audit mixes paper quality with agent reading","x":"Some counted items arise from text extraction, incomplete access to Extended Data, or two model readings that disagree. These are agent-side or access-side, which is exactly what the framework claims to separate.","f":"Report counts after removing unverified and access-limited items, and show which papers drop out."},{"sv":"high","t":"The attribution experiment is not reported","x":"Fig. 7 sets out families that vary model, workflow and problem, and the text says cross-model comparisons were used. No per-model or per-workflow results appear, so the claim that the source and not the agent is responsible rests on narrative.","f":"Tabulate outcomes by model and workflow with run counts and intervals."},{"sv":"high","t":"The match has no tolerance and a conflicting sample size","x":"Two paths lie within about $0.6\\%$ of $2.70\\kpc$. The best one uses about 30,000 stars where the paper reports 18,000 to 20,000, and no sample definition in the grid reaches that range.","f":"Pre-state a tolerance. Explain the sample-size gap or show it is irrelevant to $\\sigma$."},{"sv":"high","t":"Central case undercuts the headline framing","x":"The decisive correction was in the paper, so the central failure was agent-side. The 11 of 13 headline is about under-specification. They are different phenomena.","f":"Separate the claims and give each its own evidence."},{"sv":"med","t":"A low bar for “ambiguity” and no severity grading","x":"Any fork counts. Only the Rix case is quantified for consequence, and it is not among the thirteen.","f":"Run a miniature sensitivity analysis per paper and report the share of consequential ambiguities."},{"sv":"med","t":"No human baseline","x":"Without expert or student reproducers on the same task, 11 of 13 cannot be read as a property of the papers rather than of agents.","f":"Give the same public materials to human reproducers and compare resolved forks."},{"sv":"med","t":"One narrative case supports the mechanism","x":"Present-but-unlinked information is shown once, with no ablation, no run counts, and no statement of who enumerated the factors.","f":"Prompt ablations, structured dependency extraction, and counts across papers."},{"sv":"med","t":"Blinding and leakage rest on attestation","x":"The team knew the target and the earlier mismatch. Rix et al. (2022) predates the models, so memorised values cannot be excluded.","f":"Use post-cutoff papers, mask target numbers, and release logs."},{"sv":"med","t":"The title promises evaluation, the paper gives none","x":"There is no score, success rate or comparison between agents. The contribution is a method and a qualitative finding.","f":"Define metrics, such as link recall against annotated dependency edges."},{"sv":"med","t":"“Implicit” and “tacit” are blurred","x":"Unwritten conventions can be written down. Polanyi’s tacit knowledge cannot. “Causal relevance” is also used informally.","f":"Define terms and distinguish omitted, conventional and truly tacit knowledge."},{"sv":"low","t":"Small, partly interpretive coding","x":"$N=13$, labels reconciled by an adjudicator and one expert review, with no inter-rater statistic. The authors concede others could code differently.","f":"Report agreement between independent coders."},{"sv":"low","t":"Incomplete artefacts in this version","x":"Model identifiers, decoding settings, seeds, run counts, DOI and lockfile are placeholders.","f":"Complete before submission; this is crucial for a reproducibility paper."}],"IMPROVE":[["Experiment","Report the A, B and C families","Outcomes by model, workflow and paper with run counts and intervals. Shows whether failure sits with the agent or the source."],["Experiment","Perturb a paper on purpose","Remove or alter a stated correction in a copy of a paper and see whether the agent notices. This measures linking directly."],["Experiment","Prompt and notes ablations","Ask about calibration corrections, or change the Reader’s notes format, to separate reasoning limits from compression."],["Experiment","Human baseline","Give experts and graduate students the same public material and compare how they resolve forks."],["Reporting","Pre-state tolerances and success criteria","Use equivalence-style thresholds and report all paths within them, not only the closest."],["Reporting","Explain the sample-size gap","Show why 30,000 stars gives the published $\\sigma$ while the paper reports 18,000 to 20,000."],["Reporting","Audit reliability","Cohen’s $\\kappa$ between independent coders, and a table of which items survive human review."],["Extension","Severity-weighted audit","Run a small sensitivity analysis for every paper so ambiguity is weighted by its effect on the headline number."],["Extension","Leakage controls","Add papers after the models’ training cutoffs, mask target numbers and add canary checks."],["Extension","Annotated dependency graphs","Have authors label the ground-truth links between facts and computations, and score agents by link recall."]],"TALK":[[2,"Motivation: scientific AI has no ground truth","overview"],[2,"Reproduction as an instrument, not a goal","overview"],[2,"Three explanations for a failed reproduction","overview"],[3,"Background: Gaia parallaxes and Rix et al. (2022)","background"],[3,"System: Hermes and the five roles","agents"],[3,"Workflow: pipeline and mismatch-tracing loop","workflows"],[3,"First failure on the ApJ paper","case"],[3,"The Nature audit: 11 of 13","audit"],[3,"Design of the twelve-path experiment","case"],[4,"Results: $2.16$ to $3.53\\kpc$ and the matching path","case"],[3,"The $+0.02\\mas$ story","case"],[4,"Critique: evidence and confounds","critique"],[3,"Critique: assumptions and improvements","assumptions"],[2,"Takeaways and discussion","kit"]],"QA":[["Isn’t 11 of 13 just saying that papers are short?","Partly. Nature papers have strict length limits and put detail in Methods and Extended Data. Without a human baseline or severity grading, 11 of 13 measures how often an agent restricted to public text met an unspecified choice, not how often a paper is deficient."],["How can the blinding claim hold if the team knew $2.7\\kpc$?","The claim is narrow: the grid, labels and stopping rule were fixed before any run and the target was not used to select or stop. The team still knew the target and the earlier mismatch when choosing the three factors, and models may have seen Rix et al. in training."],["Is the matching path just the obvious reading of the method?","It uses the stated $\\MH$ cut, full sky and the $+0.02\\mas$ value that the paper reports, so it is arguably the most literal reading. That makes the first failure look agent-side and weakens the under-specification story for this case."],["Why does the paper not report results by model?","The manuscript says at least two models were used for every analysis and describes cross-model comparisons, but gives no per-model numbers, and model identifiers are placeholders. This is a gap worth raising."],["Does a cross-model audit remove bias?","It reduces dependence on one model’s habits. It assumes independent errors, which is doubtful for models trained on overlapping data, so agreement is weaker evidence than it looks."],["How does this relate to the many-analysts literature?","The twelve-path design is a small, systematic version of the same idea: a single dataset, plausible analytic choices, a wide spread of results. The paper does not cite that work, but the connection is natural."],["Could memorisation explain the match?","It cannot be excluded. Rix et al. (2022) predates the models, and the $2.7\\kpc$ value is in the abstract-level content. Post-cutoff papers and masked targets would address this."],["What should authors do differently?","State tolerances, say why a correction or cut is applied and when it would need revisiting, release machine-readable configurations, and mark which numbers are inputs versus results."],["Is reproduction a good proxy for discovery?","It tests reading, execution and reconstruction of method. It does not test hypothesis generation or choosing what to study. The authors present it as complementary and claim no discovery."],["What is the single most important result?","That a numerical match is not evidence of reconstructed reasoning: plausible choices span about half the published value, and the decisive information can sit in the text unlinked."]],"QUIZ":[{"q":"How does the paper define a paper that lacks a uniquely specified reproduction path?","o":["Its headline number cannot be matched to three significant figures","At least one ambiguity forces an independent agent to make a choice the paper does not uniquely determine","The authors refuse to share data","The two models disagree on the final answer"],"a":1,"e":"§3.4: a methodological, configurational or interpretational ambiguity that requires an undetermined choice."},{"q":"How many analysis paths does the controlled design contain, and where does the number come from?","o":["12, from 3 sample definitions $\\times$ 2 sky masks $\\times$ 2 zero-point treatments","12, from twelve different language models","6, from $3\\times 2$","13, one per Nature paper"],"a":0,"e":"A full factorial: $3\\times 2\\times 2=12$."},{"q":"What range of $\\sigma_{\\mathrm{RGC}}$ did the twelve paths produce?","o":["$1.0$ to $2.0\\kpc$","$2.16$ to $3.53\\kpc$","$2.65$ to $2.75\\kpc$","$3.0$ to $5.0\\kpc$"],"a":1,"e":"All twelve executed and produced $2.16$ to $3.53\\kpc$, with one path near 2.70."},{"q":"Which information did the agents fail to connect to the downstream fit?","o":["A missing Gaia data release","The $+0.02\\mas$ zero-point correction, already stated and cited in the paper","The Galactocentric solar distance","The number of MCMC walkers"],"a":1,"e":"The value was in the text; its causal relevance was not recognised until the experiment made the effect visible."},{"q":"What is the denominator for the audit category counts?","o":["11, the affected papers","13, the papers audited, since categories overlap","34, the references","14, the full corpus"],"a":1,"e":"Categories are not mutually exclusive, so the denominator is 13."},{"q":"Which role resolves disagreements between execution and verification?","o":["Reader","Planner","Adjudicator, through cross-model audit","Coder, by rerunning"],"a":2,"e":"Cross-model audit replaces self-confirmation."},{"q":"From the twelve values, which factor has the largest main effect?","o":["Sky mask","Parallax zero-point","Sample definition","All are equal"],"a":2,"e":"Level means are about 3.11 for metal-poor against about 2.20 and 2.19 for the $\\SN$-based samples, a swing near $0.92\\kpc$, versus 0.26 for zero-point and 0.02 for mask."},{"q":"Which observation most weakens a pure “the paper was under-specified” reading of the Rix case?","o":["The sky mask barely matters","The decisive correction was already stated in the paper","Twelve paths executed successfully","Two models were used"],"a":1,"e":"If the information was present, the first failure was partly agent-side."},{"q":"How does the matching path’s sample size compare with the paper’s?","o":["About 30,000 against a published 18,000 to 20,000","About 18,000 against 30,000","They are identical","About 5,000 against 20,000"],"a":0,"e":"The match in $\\sigma$ coexists with an unexplained difference in N."},{"q":"Why does the paper insist the published value was never an optimisation target?","o":["To rule out reverse-engineering: the matching path was identified only after all paths ran","Because the value is unknown","Because the models refused","To reduce runtime"],"a":0,"e":"It is the paper’s blinding statement."}],"GLOSS":[["Parallax ($\\varpi$)","b","The apparent annual shift of a star’s position, measured in milliarcseconds ($\\mathrm{mas}$). Distance is roughly its inverse."],["$\\mathrm{mas}$ and $\\mathrm{kpc}$","b","Milliarcsecond (a thousandth of an arcsecond) and kiloparsec (about 3,260 light-years)."],["Gaia EDR3","b","The 2020 early third data release of ESA’s Gaia mission, with astrometry for over a billion stars."],["Parallax zero-point","b","A small systematic offset in Gaia parallaxes, depending on magnitude, colour and position. Corrected by adding a shift, here $+0.02\\mas$."],["Parallax $\\SN$","b","Parallax divided by its uncertainty. Cutting at $\\SN\\ge 5$ keeps well-measured, mostly nearer stars."],["RUWE","b","Renormalised unit weight error: a Gaia fit-quality statistic. Values above about 1.4 suggest a poor astrometric solution."],["$\\MH$","b","Logarithmic metal abundance relative to the Sun. $\\MH\\lt -1.5$ means very metal-poor."],["MDF","b","Metallicity distribution function: how $\\MH$ is distributed among the stars of a sample."],["$\\sigma_{\\mathrm{RGC}}$","p","The paper’s spatial scale for the metal-poor population around the Galactic centre, about $2.7\\kpc$."],["source_id cross-match","p","Joining catalogues on Gaia’s unique source identifier, then auditing duplicates and missing rows."],["ADQL","b","Astronomical Data Query Language, an SQL-like language used to query the Gaia archive."],["MAST and TESS","b","The Mikulski Archive for Space Telescopes and the Transiting Exoplanet Survey Satellite, named among available archives."],["Tacit knowledge","b","Knowledge people have but cannot fully articulate (Polanyi 1966). The paper uses “implicit” more loosely."],["Provenance","p","A record linking each result to the data, code and parameter choices that produced it."],["Cross-model audit","p","Having a different foundation model check a result, to avoid an agent confirming its own work."],["ReAct","b","An agent pattern that alternates reasoning steps with tool actions and observations."],["Sensitivity analysis","b","Varying analysis choices systematically to see how much the conclusion moves."],["Forking paths","b","The multiplicity of defensible analytic choices (Gelman and Loken 2013) that can change results."],["$\\sigma$-clipping","b","Iteratively discarding outliers beyond a chosen number of standard deviations. Mentioned as unspecified in one audited paper."],["MCMC","b","Markov chain Monte Carlo sampling for posterior distributions; settings and convergence criteria are often omitted."],["PSF","b","Point spread function: the instrument’s blur pattern, needed for morphology fitting."]],"FIGS":[{"id":"fig-paths","title":"The twelve analysis paths","cap":"Values of $\\sigma_{\\mathrm{RGC}}$ for each path, transcribed from the labels in Fig.~8 of the paper. Hollow marker: no zero-point correction; filled: $+0.02\\mas$. The dashed line marks the published value.","alt":"Dot plot of twelve values from 2.16 to 3.53 kpc grouped by sample definition and sky mask."},{"id":"fig-agents","title":"Agent architecture on Hermes","cap":"Five specialised roles scheduled by Hermes, with a verifier-to-coder feedback loop and an inferred re-planning loop (dashed). Foundation models, the provenance filesystem and the toolchain are shared layers.","alt":"Boxes for reader, planner, coder, verifier and adjudicator in a row with feedback loops, above three shared layers."},{"id":"fig-pipeline","title":"Five-stage reproduction pipeline","cap":"Overall workflow for paper reproduction. The agent retraces the chain of evidence from inputs (paper and public data) through an auditable process (steps, evidence and gaps) to a defensible judgment. Redrawn after Fig.~1 of Wang et al.","alt":"Five boxes in a row: read the paper, design the plan, prepare the stack, run and verify, form a judgment, under a band reading paper plus public data, steps plus evidence plus gaps, defensible judgment."},{"id":"fig-rix-loop","title":"The mismatch-tracing loop on Rix et al.","cap":"Six stages from inventory to review. A mismatch is traced to the earliest unsupported assumption and the workflow resumes from the affected stage. Redrawn after Fig.~3.","alt":"Six stages with a return arrow from diagnosis back to the earliest affected stage."},{"id":"fig-attribution","title":"Attribution logic","cap":"Every observed difference is attributed to the foundation model, the agent workflow or the published method. Controlled families vary one factor and lock the other two. Redrawn after Figs.~2 and 7.","alt":"Three suspects feeding an observed difference, and a three-row grid of varied and locked factors."},{"id":"fig-master-flow","title":"Master workflow with decision points","cap":"Synthesis of the methodology: eligibility, the five roles, the mismatch test, three possible diagnoses and their feedback loops, and final human review.","alt":"Flowchart with two decision diamonds and three feedback loops leading to a final judgment."},{"id":"fig-audit","title":"Audit prevalence across 13 Nature papers","cap":"Number of papers affected by each issue category. Categories overlap, so counts must not be added. Redrawn after Fig.~6.","alt":"Horizontal bars: at least one issue 11, critical settings omitted 10, numerical conflict 8, ambiguous role 6, broken chain 6, internal contradiction 5, out of 13."},{"id":"fig-ladder","title":"Sample-size ladder for the Rix et al. reproduction","cap":"The stated cut yields 30,589 stars; the published analysis used roughly 18,000 to 20,000; explicit cut ladders give 15,063 and 13,141. Redrawn after Fig.~4.","alt":"Horizontal bars of star counts for five selection steps."},{"id":"fig-sensitivity-design","title":"Design of the twelve-path study","cap":"Three factors with two or three levels each define a full factorial of twelve paths. Grid, labels and stopping rule are frozen before any run; the published value is compared only afterwards.","alt":"A grid of 3 by 2 by 2 paths followed by a sequence of steps ending with the comparison to the published value."},{"id":"fig-effects","title":"Main effects and the zero-point interaction","cap":"Left: main effects, the range of the level means of $\\sigma_{\\mathrm{RGC}}$ for each factor. Right: the zero-point effect averaged over sky masks, for each sample definition.","alt":"Two bar charts: factor level means and the zero-point effect per sample."},{"id":"fig-zp-shift","title":"Fractional distance shift from a $0.02\\mas$ offset","cap":"$\\Delta d/d=-\\delta/(\\varpi+\\delta)$ for $\\delta=0.02\\mas$. A star near $8\\kpc$ ($\\varpi\\approx0.125\\mas$) is shifted by about $-14\\%$.","alt":"Curve of percent distance change against observed parallax on a log axis."}],"REPO":{"name":"implicit-knowledge-seminar"},"MM":{"centre":{"t":"Reproduction as a probe of implicit knowledge"},"chain":[{"t":"The question","pg":"index","b":"How do you compare AI systems on scientific discovery? A novel claim has no immediate ground truth, so there is nothing to score against.","o":"A task with a known answer."},{"t":"The instrument","pg":"index","b":"Reproduce a published result. The answer is known; the route to it is not. The agent must rebuild data selection, method and computation by itself.","o":"Whether a failed reproduction blames the agent or the paper."},{"t":"The system","pg":"agents","b":"An auditable five-role pipeline with provenance, pinned environments, cross-model audit and mandatory uncertainty reporting, so a failure can be traced instead of tuned away.","o":"Whether it works on a real paper."},{"t":"The first failure","pg":"case","b":"On Rix et al. (2022) every run recovers the qualitative result but not the numbers. The authors suspect their own system first and refine it.","o":"Is this paper unusual, or is it common?"},{"t":"The audit","pg":"audit","b":"Thirteen Nature papers, two model rounds, human review. Eleven leave at least one choice open to an agent.","o":"How much does an open choice matter to a number?"},{"t":"The pivot","pg":"index","b":"Attention moves from the agent to the information in the problem. A verified discrepancy may expose something that was never written down.","o":"A controlled test of that idea."},{"t":"The controlled test","pg":"case","b":"Twelve predefined paths through Rix et al. give $2.16$ to $3.53\\kpc$. One lands near the published $2.70\\kpc$. The $+0.02\\mas$ correction was in the text but never linked to the fit.","o":"What does a match mean, then?"},{"t":"The interpretation","pg":"contributions","b":"A match is neither necessary nor sufficient evidence of reasoning. A failure can be agent error, source underspecification or information present but unlinked.","o":"How strong is the evidence for all this?"},{"t":"The assessment","pg":"critique","b":"The design is careful and the generality and reporting are thin. The last chapters weigh both and set out what to do next.","o":""}],"branches":[{"id":"prob","n":1,"side":"r","k":"p","pg":"index","t":"The problem","d":"Why reproduction, and the question it is used to ask.","kids":[{"id":"prob1","t":"Discovery has no ground truth","d":"Novel claims cannot be checked at once, so comparing AI scientists on discovery is intractable."},{"id":"prob2","t":"Reproduction as instrument","d":"A reproduction has a known target. The agent must rebuild selection, method and computation itself."},{"id":"prob3","t":"Omissions become forks","d":"Experts fill gaps with convention. An agent meets each gap as a fork, and each fork can move the number."},{"id":"prob4","t":"Agent, paper or link?","d":"The question the framework exists to answer: is a failure the agent’s, the source’s, or information present in the paper but never linked?"}]},{"id":"bg","n":2,"side":"r","k":"b","pg":"background","t":"Background","d":"What you need to know to follow the numbers.","kids":[{"id":"bg1","t":"Gaia parallaxes","d":"Distance is the inverse of parallax, $d=1/\\varpi$. Reliable at high $\\SN$, biased and noisy at low $\\SN$."},{"id":"bg2","t":"The parallax zero-point","d":"Gaia parallaxes carry a small systematic offset. The paper applies $+0.02\\mas$ to the observed value; Lindegren et al. (2021) model it as a function of magnitude, colour and ecliptic latitude."},{"id":"bg3","t":"Rix et al. (2022)","d":"“The Poor Old Heart of the Milky Way”: metal-poor stars concentrate toward the Galactic centre, with a spatial scale $\\sigma_{\\mathrm{RGC}}\\approx2.70\\kpc$."},{"id":"bg4","t":"Agents and forking paths","d":"Language models in a tool-using loop and the push towards AI scientists, plus sensitivity analyses that make analysis choices explicit and run them all."}]},{"id":"sys","n":3,"side":"r","k":"p","pg":"agents","t":"The system","d":"The agent pipeline that makes failures traceable.","kids":[{"id":"sys1","t":"Hermes framework","d":"An open-source multi-agent framework that schedules specialised roles and gives them tools and a persistent filesystem.","pg":"agents"},{"id":"sys2","t":"Five roles","d":"Reader, Planner, Coder, Verifier and Adjudicator. Execution is kept apart from adjudication.","pg":"agents"},{"id":"sys3","t":"Safeguards","d":"Provenance, pinned environments, cross-model audit and mandatory reporting of uncertainty and failure modes.","pg":"workflows"},{"id":"sys4","t":"No training involved","d":"Inference only: no fine-tuning and no new model. The ML content is the use of language models inside an agent loop.","pg":"ai"}]},{"id":"aud","n":4,"side":"r","k":"p","pg":"audit","t":"Evidence 1: the audit","d":"Corpus-level evidence from thirteen Nature papers.","kids":[{"id":"aud1","t":"Thirteen Nature papers","d":"Papers from 2021 to 2026, run in two rounds with different models, reconciled by an adjudicator and reviewed by a human expert."},{"id":"aud2","t":"11 of 13 left a fork","d":"At least one ambiguity prevented a uniquely specified reproduction path."},{"id":"aud3","t":"2 of 13 had a clear path","d":"Only two supported an independent path from data to the target number within the task scope."},{"id":"aud4","t":"Caveat: source or reader?","d":"The count mixes under-specification with agent-side reading limits such as extraction errors and incomplete access to Extended Data."}]},{"id":"case","n":5,"side":"l","k":"p","pg":"case","t":"Evidence 2: the Rix case","d":"The in-depth test: twelve analysis paths through one paper.","kids":[{"id":"case1","t":"Right story, wrong numbers","d":"Every run recovered the qualitative result. The sample came out near 30,000 stars against 18,000 to 20,000 published."},{"id":"case2","t":"Twelve paths: $3\\times2\\times2$","d":"Sample definition, sky mask and zero-point treatment, crossed. The grid was fixed before running.","pg":"equations"},{"id":"case3","t":"$2.16$ to $3.53\\kpc$","d":"A spread of about $1.37\\kpc$, roughly half the published value, from plausible choices alone.","pg":"equations"},{"id":"case4","t":"One path near $2.70\\kpc$","d":"Path P02 gives $2.7033\\kpc$, about $0.12\\%$ from the published value. The target was never used for tuning; the match was identified after all runs."},{"id":"case5","t":"$+0.02\\mas$ was in the text","d":"The correction was stated and cited, but the agents had not linked it to the fit until its effect became visible."}]},{"id":"interp","n":6,"side":"l","k":"p","pg":"contributions","t":"Interpretation","d":"What the authors conclude from the two experiments.","kids":[{"id":"int1","t":"Three explanations","d":"Agent or tooling error, source underspecification, or failure to connect information that is already in the paper.","pg":"index"},{"id":"int2","t":"A match is weak evidence","d":"It is neither necessary nor sufficient evidence that reasoning was reconstructed, and it cannot be an optimisation target."},{"id":"int3","t":"Present but unlinked","d":"The agents retrieve facts and run procedures, but are unreliable at seeing that a stated fact governs a later step."},{"id":"int4","t":"Possible hidden knowledge","d":"Reproduction might surface relationships never made explicit. The authors claim no discovery."}]},{"id":"assess","n":7,"side":"l","k":"c","pg":"critique","t":"Assessment and next steps","d":"My assessment of the evidence, and where to take it next.","kids":[{"id":"as1","t":"Strengths","d":"A pre-specified blinded factorial design, separation of execution from adjudication, and candour about the first failure.","pg":"critique"},{"id":"as2","t":"Loopholes","d":"The audit mixes source and reader, attribution results are not reported, there is no match tolerance, and the mechanism rests on one narrative case.","pg":"synthesis"},{"id":"as3","t":"Assumptions","d":"Nineteen are listed, from reproduction as a proxy for reasoning to a constant zero-point model.","pg":"assumptions"},{"id":"as4","t":"Next steps","d":"Report the attribution families, perturb a paper on purpose, add a human baseline and scale up.","pg":"synthesis"}]}],"links":[{"a":"prob3","b":"aud2","t":"A claim and its test","d":"The claim that omissions become forks is exactly what the audit counts. Eleven of thirteen is the evidence offered for it."},{"a":"bg2","b":"case5","t":"Background that mattered","d":"The zero-point offset is the fact the agents did not link. Knowing that it is a systematic correction is what lets an expert see why it belongs in the fit."},{"a":"sys3","b":"int1","t":"Safeguards separate causes","d":"Provenance, verification and cross-model audit are what let the authors rule out agent error before blaming the source."},{"a":"case1","b":"aud1","t":"A failure led to the audit","d":"The first mismatch is why the authors refined the pipeline and moved on to a batch of thirteen papers."},{"a":"case3","b":"int2","t":"The spread implies the interpretation","d":"If plausible choices alone move the answer by half its value, one matching number proves little."},{"a":"case5","b":"int3","t":"One case, one mechanism","d":"The unlinked correction is the only direct evidence for the claim about failing to connect information."},{"a":"prob4","b":"int1","t":"Question and answer","d":"The question posed at the start is answered by the three-way split of explanations."},{"a":"aud4","b":"as2","t":"A caveat becomes a loophole","d":"Mixing source and reader errors in one count is the first loophole in the assessment."},{"a":"as4","b":"int3","t":"A test of linking","d":"Perturbing a paper on purpose, for instance by altering a stated correction, would measure linking directly."}]},"SYN":{"glance":[{"t":"What holds up","c":"p","x":["The twelve-path design is transparent and pre-specified, and its spread of $2.16$ to $3.53\\kpc$ is vivid.","A matching number is weak evidence of reconstructed reasoning, and the spread shows why.","Keeping execution apart from adjudication is a sound guard against self-confirmation."]},{"t":"What is exposed","c":"c","x":["The audit headline mixes paper quality with how the agent read the paper.","The central mechanism, information present but unlinked, rests on one narrative case.","There is no per-model result, human baseline or match tolerance."]},{"t":"What to do next","c":"b","x":["Report outcomes by model, workflow and paper, with run counts.","Test linking directly by altering a stated correction in a copy of a paper.","Add a human baseline and post-cutoff papers, then widen beyond one quantity."]}],"find":[{"id":"F1","c":"p","ev":2,"pg":"audit","t":"Eleven of thirteen Nature papers left at least one choice open","x":"At least one methodological, configurational or interpretational ambiguity prevented a uniquely specified reproduction path.","w":"Fig. 6 and Appendix A","cv":"The threshold is low, N is 13, and the count mixes source quality with agent reading."},{"id":"F2","c":"p","ev":2,"pg":"audit","t":"Only two papers supported an independent data-to-number path","x":"Only these two gave methodological descriptions complete enough, within the scope of the tasks, to support an independent path from data to the target result.","w":"Fig. 6 and §4.2","cv":"Scope-limited: it describes what an agent could do from public material, not what an expert could."},{"id":"F3","c":"p","ev":4,"pg":"case","t":"Twelve paths gave $\\sigma_{\\mathrm{RGC}}$ from $2.16$ to $3.53\\kpc$","x":"Crossing three choices (sample, sky mask, zero-point) gives a spread of about $1.37\\kpc$, roughly half the published value.","w":"Fig. 8 and §4.3","cv":"One quantity in one paper. Values are transcribed from labels printed in the figure."},{"id":"F4","c":"p","ev":3,"pg":"case","t":"The published value was never a target, and one path lands close to it","x":"Path P02 gives $2.7033\\kpc$, about $0.12\\%$ from $2.70\\kpc$. A second path, P04, is about $0.56\\%$ away.","w":"§3.5 and §4.3","cv":"Blinding is self-attested, no tolerance was set, and P02 uses about 30,000 stars where the paper reports 18,000 to 20,000."},{"id":"F5","c":"c","ev":3,"pg":"case","t":"Sample definition moves the answer most, and the zero-point effect changes sign","x":"From the twelve values: sample definition swings $\\sigma_{\\mathrm{RGC}}$ by $0.92\\kpc$, the zero-point by $0.26\\kpc$ and the sky mask by $0.02\\kpc$. The $+0.02\\mas$ correction lowers $\\sigma$ by $0.83\\kpc$ on average for the metal-poor sample and raises it by $0.03$ to $0.04\\kpc$ for the $\\SN$-selected ones.","w":"My arithmetic on Fig. 8 values","cv":"Descriptive only. It rests on twelve transcribed numbers and no uncertainties."},{"id":"F6","c":"p","ev":2,"pg":"contributions","t":"Agents retrieve and execute, but are unreliable at linking","x":"The $+0.02\\mas$ correction was in the paper and cited, yet the agents had not recognised that it governs the fit.","w":"§4.3 and §6","cv":"One narrative case, with no ablation, no run counts and no test of a prompt or context limit."},{"id":"F7","c":"p","ev":4,"pg":"contributions","t":"A numerical match is not reliable evidence of reconstructed reasoning","x":"It follows from F3: when plausible choices alone move the answer by about half its value, one match says little about the route taken.","w":"Abstract, §6 and §8","cv":"Sound logic, but the conclusion is about this one quantity, not about agents in general."},{"id":"F8","c":"p","ev":1,"pg":"contributions","t":"Reproduction might reveal hidden knowledge","x":"A verified discrepancy could expose relationships among data, method and conclusion that were never made explicit.","w":"§4.2 and §8","cv":"Offered as a possibility. The authors claim no new discovery."}],"stated":[{"t":"A small, staged corpus","x":"One in-depth ApJ case and thirteen Nature papers, not one uniform benchmark of fourteen."},{"t":"Astronomy only","x":"A data-rich field with unusually open archives. The frequency and character of implicit dependencies may differ elsewhere."},{"t":"Partly interpretive coding","x":"Audit categories came from two model rounds, an adjudicator and human review, and another team could code them differently."},{"t":"Results age quickly","x":"Model capabilities and versions change, so absolute failure rates are time-dependent. The paper offers a mechanism and a method, not a permanent number."},{"t":"Moving data and materials","x":"Reproduction depends on data releases and on how complete the public material is, and both can change."},{"t":"One quantity in one paper","x":"The twelve-path analysis concerns a single quantity. Broader generalisation needs larger and more diverse corpora."}],"matrix":{"cols":["Construct validity","Internal validity","External validity","Reporting"],"sub":["Does it measure what it claims?","Are there confounds or leaks?","Does it generalise?","Can it be checked?"],"rows":[{"f":"F1","t":"11 of 13 left a fork","m":[[2,"Any fork counts; no severity grade"],[2,"Reader-side items are counted as source gaps"],[1,"Thirteen papers from one field"],[2,"Audit table not in the manuscript"]]},{"f":"F3","t":"Twelve paths, $2.16$ to $3.53\\kpc$","m":[[0,"The spread is read straight from the values"],[1,"The authors chose the factors and levels"],[2,"One quantity in one paper"],[1,"Configurations promised in a package"]]},{"f":"F4","t":"One path near the published value","m":[[2,"No tolerance defined for a match"],[1,"Blinding self-attested; sample-size gap"],[2,"One paper"],[1,"Logs not released"]]},{"f":"F6","t":"Present but unlinked","m":[[1,"“Causal relevance” used informally"],[2,"A prompt or context limit is not excluded"],[2,"One case"],[2,"No run counts, no ablation"]]},{"f":"F7","t":"A match is weak evidence","m":[[1,"“Reasoning reconstructed” is not measured independently"],[0,"Follows from the spread"],[1,"Shown for one quantity"],[0,"Follows from the printed values"]]}]},"future":[{"h":"Near term","s":"With the data already in hand","i":[{"c":"c","t":"Report the attribution families","x":"Tabulate outcomes by model, workflow and paper, with run counts and intervals."},{"c":"c","t":"Rebuild the 11 of 13 count","x":"Recount after removing unverified and access-limited items, and show which papers drop out."},{"c":"c","t":"Set a tolerance, explain the sample size","x":"State what counts as a match in advance, and show why 30,000 stars can give the published $\\sigma$ when the paper reports 18,000 to 20,000."},{"c":"c","t":"Release logs and the audit table","x":"Complete the model identifiers, decoding settings, seeds, run counts and lockfile that this version leaves as placeholders."}]},{"h":"Next study","s":"New experiments on the same design","i":[{"c":"c","t":"Perturb a paper on purpose","x":"Remove or alter a stated correction in a copy of a paper and see whether the agent notices."},{"c":"c","t":"Prompt and notes ablations","x":"Ask about calibration corrections, or change the Reader’s note format, to separate reasoning limits from compression."},{"c":"c","t":"A human baseline","x":"Give experts and graduate students the same public material and compare how they settle each fork."},{"c":"c","t":"A severity-weighted audit","x":"Run a small sensitivity analysis for every paper so each ambiguity is weighted by its effect on the headline number."},{"c":"c","t":"Post-cutoff papers and canaries","x":"Add papers published after the models’ training cutoffs, mask target numbers and plant canary checks."}]},{"h":"Longer term","s":"Where the authors want to go","i":[{"c":"p","t":"Reproduce at scale","x":"The authors’ stated next goal: move from dozens of papers to hundreds or thousands, so recurring parameter conflicts and failure modes can reveal patterns that transfer across papers and disciplines."},{"c":"c","t":"Other disciplines","x":"Repeat in fields with less open data, where the frequency and character of implicit dependencies may differ."},{"c":"c","t":"Dependency graphs and link recall","x":"Have authors annotate the true links between facts and computations, and score agents by how many links they recover."},{"c":"c","t":"Agents that ask","x":"Let an agent flag a fork and put the question to a domain expert instead of forcing an answer."},{"c":"c","t":"A reproduction card for authors","x":"A short structured declaration of data version, selection cuts, calibration corrections and tolerances, so implicit choices become explicit at the source."}]}],"method":[{"s":"Corpus selection","now":"Papers with public data, enough concrete material and a broadly accepted conclusion.","gap":"Small N, one field, and no control for memorisation.","fix":"Stratify by field and date, add papers after the models’ cutoffs and mask target numbers.","show":"Whether the share of open forks survives outside astronomy and without recall."},{"s":"Audit coding","now":"Two model rounds, an adjudicator and one expert review.","gap":"No agreement statistic, any fork counts, and reader-side errors are mixed in.","fix":"Independent human coders with Cohen’s $\\kappa$, a severity grade per fork and access-limited items kept apart.","show":"How interpretive the labels are and how many forks matter."},{"s":"Attribution of failure","now":"Cross-model comparisons are described but not reported.","gap":"The agent cannot be told apart from the source.","fix":"Tabulate outcomes by model, workflow and paper with run counts, and add a human baseline.","show":"Whether failures follow the agent or the paper."},{"s":"Sensitivity analysis","now":"Three factors, twelve paths, blinded, one quantity in one paper.","gap":"The factors were chosen by the authors, and configurations are not yet released.","fix":"Elicit factors from several experts independently, repeat on a second quantity and paper, and publish the configurations.","show":"Whether a $1.37\\kpc$ spread is typical."},{"s":"Success criterion","now":"Closeness to the published number, with no stated tolerance.","gap":"A number can match for the wrong reasons.","fix":"Pre-state equivalence thresholds, report every path inside them, and score reasoning through dependency links.","show":"The difference between matching and reconstructing."},{"s":"Mechanism test","now":"One narrative case of an unlinked correction.","gap":"No ablation, and a prompt or context limit is not excluded.","fix":"Alter or remove the correction in a copy, run prompt ablations and vary the Reader’s note format.","show":"Whether the failure is one of linking or of compression."},{"s":"Reporting","now":"Placeholders for model identifiers, decoding settings, seeds and run counts.","gap":"Not reproducible as written, which matters for a reproducibility paper.","fix":"Complete the artefacts, pin the data versions and release logs.","show":"That the paper meets its own standard."}]}};
